-- Import des courriers arrivées 2022
-- Source : 2022.xlsx (feuille 2022).
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N° ARRIVEES            -> txt_numdordre (00001/jj-mm-aaaa)
--   DATE RECEPTION         -> dt_datearrivee
--   REFERENCE              -> txt_reference ; N° et date du courrier extraits
--   PRENOMS + NOMS         -> txt_prenomNom et txt_expediteur
--   objet                  -> txt_objet (libellé d'origine)
--   objet                  -> txt_designation (liste designationsParCategorie)
--   designation retenue    -> txt_categorie
--   N° TF                  -> txt_numTitreFoncier
--   ANCIEN N° TF           -> txt_numTitreMere s'il s'agit d'un titre, sinon situation
--   N° LOT                 -> txt_numLot
--   SUPERFICIE             -> txt_superficie
--   SITUATION/LOTISSEMENT  -> txt_lotissement
--   AGENTS TRAITEURS       -> txt_agenttraiteur
--   OBSERVATIONS           -> txt_observation
--   DATE DEPART            -> ajoutée à txt_observation
--   NICAD cité dans l'objet -> txt_NICAD
-- Une référence qui n'est qu'une date Excel est lue comme date du courrier.
--
-- Champs obligatoires absents du classeur :
--   txt_typecourrier = BE si l'objet commence par « BE », sinon Individuel
--   txt_nombrepiece  = 1
--   expéditeur ou agent vide -> Non renseigné
-- Référence absente : « <N°> du jj-mm-aaaa », comme le formulaire.
-- Références en doublon : suffixe [n° d'ordre].
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Lignes importées : 2119
-- Lignes non importées :
--   ligne Excel 1635 : N° d'arrivée absent, non importée (Assane NDIAYE / Morcellement)
--   ligne Excel 1636 : N° d'arrivée absent, non importée (Aminata Bintou Wakhab NDOYE / Morcellement)
--
-- Répartition des catégories :
--    1926  Demande SERVICES
--     115  Réquisition - Instruction
--      63  Information
--      14  Convocation - Invitation
--       1  Réclamation - Signalement
-- Désignations :
--    1121  Morcellements
--     245  Demande de Régularisation par voie de Bail
--     235  Demande de Cession définitive
--     115  Instruction à suivre
--     106  Demande de situation foncière
--      41  Demande d'états des lieux
--      34  Demande de délimitation
--      34  Transmission lettre
--      31  Demande de CIC
--      27  Demande de terrain/Echange
--      26  Duplication de CIC
--      18  Tribunal
--      12  Décision - Arrêté
--      12  Demande d'extraits de plan
--      10  Autorisation de lotir
--       8  Réquisition d'immatriculation
--       6  Autres
--       5  Visite de site
--       5  Note de service
--       4  Formation
--       4  Réunion
--       4  Réceptions de lotissements
--       3  Demande d'évaluation
--       2  Litiges
--       2  Lettre
--       2  Document administratif
--       2  Demande de Titre foncier
--       1  Cérémonie
--       1  Demande d'attestation du Cadastre
--       1  Circulaire
--       1  PV - Compte - rendu
--       1  Alerte

SET NAMES utf8mb4;

START TRANSACTION;







COMMIT;
